    {
      "id": "context",
      "turnIds": [
        "T02",
        "T03",
        "T04"
      ],
      "screenText": "UUID is the key",
      "visualBeat": "Schema diagram highlighting the UUID field as the primary key, dimming the title field.",
      "factIds": [
        "u1"
      ]
    },
    {
      "id": "beat-1",
      "turnIds": [
        "T05",
        "T06"
      ],
      "screenText": "Name lookup fails",
      "visualBeat": "Illustration of a request arrow hitting a wall labeled 'Title', returning an error icon.",
      "factIds": [
        "u1",
        "u5"
      ]
    },
    {
      "id": "beat-2",
      "turnIds": [
        "T07"
      ],
      "screenText": "Fetching by UUID",
      "visualBeat": "Terminal window showing a GET request with the specific UUID string.",
      "factIds": [
        "u2",
        "u3"
      ]
    },
    {
      "id": "beat-3",
      "turnIds": [
        "T08",
        "T09",
        "T10"
      ],
      "screenText": "Keyboard returned, stock 12",
      "visualBeat": "JSON response object displaying the keyboard title and stock value 12 with a green checkmark.",
      "factIds": [
        "u2",
        "u3"
      ]
    },
    {
      "id": "payoff",
      "turnIds": [
        "T11",
        "T12",
        "T13"
      ],
      "screenText": "Names for humans, IDs for machines",
      "visualBeat": "Split screen: left side shows a human-readable label, right side shows a machine-readable UUID.",
      "factIds": [
        "u1"
      ]
    },
    {
      "id": "cta",
      "turnIds": [
        "T14"
      ],
      "screenText": "Don't confuse them",
      "visualBeat": "Bold text overlay with a subtle fade-out effect, emphasizing the final lesson.",
      "factIds": [
        "u1",
        "u5"
      ]
    }
  ],
  "editorNotes": "Scenes strictly follow the locked transcript order. Visuals are labeled as illustrations where depicting abstract concepts or failed states not explicitly shown in code. Facts u1-u5 support the technical accuracy of the key vs. title distinction and the specific demo data."
}

