      "visualBeat": "Calendar page flips to Q1 2027 with a 'Planned' tag.",
      "factIds": [
        "f4"
      ]
    },
    {
      "id": "cta",
      "turnIds": [
        "T13",
        "T14"
      ],
      "screenText": "Treat as roadmap, not switch",
      "visualBeat": "Roadmap line extends forward; 'Evaluate' button appears.",
      "factIds": [
        "f4",
        "f5"
